import React, { useState, useEffect } from "react";
import "./SolovievPortfolio.css";
import { motion, AnimatePresence } from "framer-motion";

export default function SolovievPortfolio() {
  const images = [
    "/images/pic1.jpg",
    "/images/pic2.jpg",
    "/images/pic3.jpg",
    "/images/pic4.jpg",
    "/images/pic5.jpg",
  ];

  const [index, setIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setIndex((prev) => (prev + 1) % images.length);
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="hero-container">
      <AnimatePresence>
        <motion.div
          key={index}
          className="hero-bg"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 1.5 }}
          style={{ backgroundImage: `url(${images[index]})` }}
        />
      </AnimatePresence>

      <div className="hero-content">
        <h1 className="hero-title">Soloviev Team</h1>
        <p className="hero-subtitle">Отделка и ремонт помещений любой сложности</p>
      </div>
    </div>
  );
}
